<!--more-->

#### Aes是什么

在密码学中又称Rijndael加密法，是美国联邦政府采用的一种区块加密标准, 是对称密钥加密中最流行的算法之一

#### Aes加密

```cs
/// <summary>
/// Aes加密 
/// </summary>
/// <param name="text">明文</param>
/// <param name="password">密钥</param>
/// <param name="iv">偏移量</param>
/// <returns>密文</returns>
public static string AesEncrypt(string text, string password, string iv)
{

    byte[] pwdBytes = Encoding.UTF8.GetBytes(password);
    byte[] keyBytes = new byte[16];
    int len = pwdBytes.Length;
    if (len > keyBytes.Length)
        len = keyBytes.Length;
    Array.Copy(pwdBytes, keyBytes, len);
    RijndaelManaged rhinelandCipher = new RijndaelManaged()
    {
        Mode = CipherMode.CBC,
        Padding = PaddingMode.Zeros,
        KeySize = 128,
        BlockSize = 128,
        Key = keyBytes,
        IV = Encoding.UTF8.GetBytes(iv)
    };

    ICryptoTransform transform = rhinelandCipher.CreateEncryptor();
    byte[] plainText = Encoding.UTF8.GetBytes(text);
    byte[] cipherBytes = transform.TransformFinalBlock(plainText, 0, plainText.Length);

    return Convert.ToBase64String(cipherBytes);

}
```

#### Aes解密

```cs
/// <summary>
/// Aes解密
/// </summary>
/// <param name="text">密文</param>
/// <param name="password">密钥</param>
/// <param name="iv">偏移量</param>
/// <returns>明文</returns>
public static string AesDecrypt(string text, string password, string iv)
{
    byte[] encryptedData = Convert.FromBase64String(text);
    byte[] pwdBytes = Encoding.UTF8.GetBytes(password);
    byte[] keyBytes = new byte[16];
    int len = pwdBytes.Length;
    if (len > keyBytes.Length) 
        len = keyBytes.Length;
    Array.Copy(pwdBytes, keyBytes, len);
    RijndaelManaged rhinelandCipher = new RijndaelManaged()
    {
        Mode = CipherMode.CBC,
        Padding = PaddingMode.Zeros,
        KeySize = 128,
        BlockSize = 128,
        Key = keyBytes,
        IV = Encoding.UTF8.GetBytes(iv)
    };

    ICryptoTransform transform = rhinelandCipher.CreateDecryptor();
    byte[] plainText = transform.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
    return Encoding.UTF8.GetString(plainText);
}
