using Caty.Album.Dal.Interface;
using Caty.Album.Model;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Caty.Album.Dal.Implements
