                                    SET [UserName] = @UserName
                                    ,[Password] = @Password
                                    ,[Gender] = @Gender
                                    ,[Birthday] = @Birthday
                                    ,[UpdateUserId] = @UpdateUserId
                                    ,[UpdateDate] = @UpdateDate
                                    ,[IsDeleted] = @IsDeleted
                                    WHERE Id = @Id";
                return conn.Execute(updateSql, entity) > 0;
            }
        }
    }
}
